import{_ as p,a0 as d,w as a,s as l,I as i,x as o,a1 as t,A as n,ao as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const U=JSON.parse('{"title":"如何在Docker容器中运行GUI程序 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Docker容器中运行GUI程序 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Docker容器中运行GUI程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Docker容器中运行GUI程序 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150409 How to Run GUI Apps in a Docker Container","title":"如何在Docker容器中运行GUI程序","tag":"201504","desc":""},"relativePath":"201504/20150409 How to Run GUI Apps in a Docker Container.md","filePath":"[post].md"}'),c={name:"201504/20150409 How to Run GUI Apps in a Docker Container.md"};function k(u,e,f,m,D,x){const r=d("Link");return a(),l("div",null,[e[16]||(e[16]=i("h1",{id:"如何在docker容器中运行gui程序",tabindex:"-1"},[o("如何在Docker容器中运行GUI程序 "),i("a",{class:"header-anchor",href:"#如何在docker容器中运行gui程序","aria-label":"Permalink to “如何在Docker容器中运行GUI程序”"},"​")],-1)),i("p",null,[e[1]||(e[1]=o("各位，今天我们将学习如何在",-1)),t(r,{href:"http://docker.io/"},{default:n(()=>[...e[0]||(e[0]=[o("Docker",-1)])]),_:1}),e[2]||(e[2]=o("之中运行GUI程序。我们可以轻易地在Docker容器中运行大多数GUI程序且不出错。Docker是一个开源项目，提供了一个打包、分发和运行任意程序的轻量级容器的开放平台。它没有语言支持、框架或者打包系统的限制，并可以运行在任何地方、任何时候，从小型的家用电脑到高端的服务器都可以运行。这让人们可以打包不同的包用于部署和扩展网络应用，数据库和后端服务而不必依赖于特定的栈或者提供商。",-1))]),e[17]||(e[17]=s(`<p>下面是我们该如何在Docker容器中运行GUI程序的简单步骤。本教程中，我们会用Firefox作为例子。</p><h3 id="_1-安装-docker" tabindex="-1">1. 安装 Docker <a class="header-anchor" href="#_1-安装-docker" aria-label="Permalink to “1. 安装 Docker”">​</a></h3><p>在开始前，我们首先得确保在Linux主机中已经安装了Docker。这里，我运行的是CentOS 7 主机，我们将运行yum管理器和下面的命令来安装Docker。</p><pre><code># yum install docker
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/installing-docker.png" alt=""></p><pre><code># systemctl restart docker.service
</code></pre><h3 id="_2-创建-dockerfile" tabindex="-1">2. 创建 Dockerfile <a class="header-anchor" href="#_2-创建-dockerfile" aria-label="Permalink to “2. 创建 Dockerfile”">​</a></h3><p>现在，Docker守护进程已经在运行中了，我们现在准备创建自己的Firefox Docker容器。我们要创建一个Dockerfile，在其中我们要输入需要的配置来创建一个可以工作的Firefox容器。为了运行 Docker 镜像我们需要使用最新版本的CentOS。要创建 Docker 镜像，我们需要用文本编辑器创建一个名为Dockerfile的文件。</p><pre><code># nano Dockerfile
</code></pre><p>接着，在Dockerfile中添加下面的行并保存。</p><pre><code>#!/bin/bash
FROM centos:7
RUN yum install -y firefox
# 用你自己的 uid /gid 替换下面的0
RUN export uid=0 gid=0
RUN mkdir -p /home/developer
RUN echo &quot;developer:x:\${uid}:\${gid}:Developer,,,:/home/developer:/bin/bash&quot; &gt;&gt; /etc/passwd
RUN echo &quot;developer:x:\${uid}:&quot; &gt;&gt; /etc/group
RUN echo &quot;developer ALL=(ALL) NOPASSWD: ALL&quot; &gt;&gt; /etc/sudoers
RUN chmod 0440 /etc/sudoers
RUN chown \${uid}:\${gid} -R /home/developer

USER developer
ENV HOME /home/developer
CMD /usr/bin/firefox
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/Dockerfile-GUI.png" alt=""></p><p><strong>注意：在第四行的配置中，用你自己的用户和组id来替换0。 我们可以用下面的命令在shell或者终端中得到uid和gid。</strong></p><pre><code>#  id $USER
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/user-id.png" alt=""></p><h3 id="_3-构造docker容器" tabindex="-1">3. 构造Docker容器 <a class="header-anchor" href="#_3-构造docker容器" aria-label="Permalink to “3. 构造Docker容器”">​</a></h3><p>下面我们就要根据上面的Dockerfile构建一个容器。它会安装firefox浏览器和它需要的包。它接着会设置用户权限并让它可以工作。这里镜像名是firefox，你可以根据你的需要命名。</p><pre><code># docker build --rm -t firefox .
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/building-firefox-docker.png" alt=""></p><h3 id="_4-运行docker容器" tabindex="-1">4. 运行Docker容器 <a class="header-anchor" href="#_4-运行docker容器" aria-label="Permalink to “4. 运行Docker容器”">​</a></h3><p>现在，如果一切顺利，我们现在可以在运行在CentOS 7镜像中的Docker容器里面运行我们的GUI程序也就是Firefox浏览器了。</p><pre><code># docker run -ti --rm -e DISPLAY=$DISPLAY -v /tmp/.X11-unix:/tmp/.X11-unix firefox
</code></pre><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>在Docker容器中运行GUI程序是一次很棒的体验，它对你的主机文件系统没有任何的伤害。它完全依赖你的Docker容器。本教程中，我尝试了CentOS 7 Docker中的Firefox。我们可以用这个技术尝试更多的GUI程序。如果你有任何问题、建议、反馈请在下面的评论栏中写下来，这样我们可以提升或更新我们的内容。谢谢！</p><hr>`,25)),i("p",null,[e[4]||(e[4]=o("via: ",-1)),t(r,{href:"http://linoxide.com/linux-how-to/run-gui-apps-docker-container/"},{default:n(()=>[...e[3]||(e[3]=[o("http://linoxide.com/linux-how-to/run-gui-apps-docker-container/",-1)])]),_:1})]),i("p",null,[e[8]||(e[8]=o("作者：",-1)),t(r,{href:"http://linoxide.com/author/arunp/"},{default:n(()=>[...e[5]||(e[5]=[o("Arun Pyasi",-1)])]),_:1}),e[9]||(e[9]=o(" 译者：",-1)),t(r,{href:"https://github.com/geekpi"},{default:n(()=>[...e[6]||(e[6]=[o("geekpi",-1)])]),_:1}),e[10]||(e[10]=o(" 校对：",-1)),t(r,{href:"https://github.com/wxy"},{default:n(()=>[...e[7]||(e[7]=[o("wxy",-1)])]),_:1})]),i("p",null,[e[13]||(e[13]=o("本文由 ",-1)),t(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[11]||(e[11]=[o("LCTT",-1)])]),_:1}),e[14]||(e[14]=o(" 原创翻译，",-1)),t(r,{href:"http://linux.cn/"},{default:n(()=>[...e[12]||(e[12]=[o("Linux中国",-1)])]),_:1}),e[15]||(e[15]=o(" 荣誉推出",-1))])])}const b=p(c,[["render",k]]);export{U as __pageData,b as default};
